package com.spendwise.transaction;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.Map;
@RestController @RequestMapping("/api/summary") public class SummaryController{private final TransactionRepository repository;public SummaryController(TransactionRepository r){repository=r;}
@GetMapping public Map<String,BigDecimal> summary(@RequestParam String month,Authentication a){LocalDate s;try{s=LocalDate.parse(month+"-01");}catch(RuntimeException e){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Month must use yyyy-MM format");}var rows=repository.findAllByUserEmailAndDateBetweenOrderByDateDesc(a.getName(),s,s.withDayOfMonth(s.lengthOfMonth()));BigDecimal i=rows.stream().filter(t->t.getType()==TransactionType.INCOME).map(Transaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal x=rows.stream().filter(t->t.getType()==TransactionType.EXPENSE).map(Transaction::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("income",i,"expense",x,"balance",i.subtract(x));}}